import './startup.js';
import './strength-renderer.js';
import {resolveReturn} from './rejoin.js';
import {installLan} from './lan.js';
import {createHttpSession} from './transport.js';
import {mountStoryBrowser} from './story-browser.js';
for(const name of ['__stoneThrowAutoMatchMode','__stoneThrowStoryAutoResolveMode'])Object.defineProperty(window,name,{get:()=>false,configurable:false});
let localContext=true,lastError=null;function showError(error){lastError=error;if(document.body.classList.contains('st-multiplayer-mode'))localContext=false;if(localContext&&!['seat-handed-to-ai','missing-seat-credential','unknown-seat','rejoin-required'].includes(error.code)){document.body.classList.add('st-main-menu-mode');let notice=document.getElementById('stLocalRecoveryMessage');if(!notice){notice=document.createElement('p');notice.id='stLocalRecoveryMessage';notice.setAttribute('role','alert');document.querySelector('#stMainMenu .st-menu-frame').append(notice);}notice.textContent='Local game unavailable ('+(error.code||'connection-failed')+'). Return through SINGLE PLAYER or CONTINUE STORY to retry. Your saved battle has not been discarded.';return;}let box=document.getElementById('stTransportError');if(!box){box=document.createElement('div');box.id='stTransportError';box.setAttribute('role','alert');box.style.cssText='position:fixed;top:0;left:0;right:0;z-index:100001;background:#211;color:white;padding:12px';document.body.append(box);}box.replaceChildren(document.createTextNode((error.code==='seat-handed-to-ai'?'This seat has already been handed to AI.':error.code==='missing-seat-credential'?'Your multiplayer seat credential is missing.':error.code==='unknown-seat'?'This multiplayer seat is no longer available.':'Local host: '+(error.code||'connection-failed')+'.')+' '));const retry=document.createElement('button');retry.textContent='REJOIN';retry.onclick=()=>location.reload();box.append(retry);if(['seat-handed-to-ai','unknown-seat','missing-seat-credential'].includes(error.code)){retry.hidden=true;const back=document.createElement('button');back.textContent='Multiplayer menu';back.onclick=async()=>{await session.request('pvp/leave');location.reload();};box.append(back);}if(error.code==='unknown-session'){const fresh=document.createElement('button');fresh.textContent='Start new local session';fresh.onclick=async()=>{await session.open(true);location.reload();};box.append(fresh);}}
const session=createHttpSession();let browserClient,lanClient;
try{const opening=await session.open();localContext=!opening.returning&&!opening.update?.lan;const opened=await resolveReturn(session,opening);browserClient=await mountStoryBrowser(session.client,{initialConfiguration:opened.configuration,localResume:opened.localResume,onError:showError,onPublicUpdate:u=>{localContext=!u.lan;lanClient?.observe(u);},additionalBlocked:()=>lanClient?.blocked(),selectMode:mode=>session.request('mode',{mode}),availableModes:opened.modes,initialMode:opened.update?.lan?'multiplayer':undefined,replaceConfiguration:next=>session.configure(next,next.story?window.__stoneThrowStoryContinuationContext?.():undefined)});lanClient=installLan(session,browserClient,opened);if(!localContext&&opened.reconnected&&!opened.multiplayerMenu&&!opened.mainMenu){document.body.classList.remove('st-main-menu-mode');}if(localContext){document.body.classList.add('st-main-menu-mode');document.getElementById('resultOverlay').style.display='none';}document.documentElement.dataset.localHost='connected';}
catch(error){showError(error);}
document.addEventListener('click',e=>{if(lastError&&localContext&&e.target.closest('#stMenuFull,#stMenuStory,#stMenuStoryContinue')){e.preventDefault();e.stopImmediatePropagation();location.reload();return;}if(lastError&&!lanClient&&e.target.closest('#stMenuOnline')){e.preventDefault();e.stopImmediatePropagation();showError(lastError);}},true);

if(browserClient){const {installNodeDevelopment}=await import("./node-development.js");installNodeDevelopment(session,browserClient);}
